// ---------------------------------------------------------------------------

export const getCmdLine = (
		cmdName: string,
		lArgs: string[]
		): string => {

	assert(isString(cmdName), `cmdName not a string: ${OL(cmdName)}`)
	assert(isArrayOfStrings(lArgs), `not an array of strings: ${OL(lArgs)}`)
	const cmdLine = `${cmdName} ${lArgs.join(' ')}`
	DBG(`cmdLine = ${OL(cmdLine)}`)
	return cmdLine
}

// ---------------------------------------------------------------------------

export type TStreamType = 'piped' | 'inherit'

export type TExecResult = {
	success: boolean
	notNeeded?: true
	stdout?: string
	stderr?: string
	infile?: string
	outfile?: string | string[]
	hPostResult?: TExecResult
}

// ---------------------------------------------------------------------------
// ASYNC

export const mkstr = (
		item: string | BufferSource
		): string => {

	return (
		  isString(item) ? stripAnsiCode(item)
		: isArray(item)  ? stripAnsiCode(item.join(''))
		:                  stripAnsiCode(decode(item))
		)
}

// ---------------------------------------------------------------------------
// ASYNC
// --- Four cases for stdout:
//        1. no callback, capture false
//           output goes directly to the console
//        2. callback defined
//           output goes to a callback function
//        3. capture is set
//           output is found in the result hash
//        4. callback defined and capture set
//           output both in result hash and goes to callback

type TExecInput = string | string[] | TIterator<string> | TAsyncIterator<string>
type TExecCallback = (str: string) => void

export const execCmd = async (
		cmdName: string,
		lArgs: string[] = [],
		hOptions: hash = {}
		): AutoPromise<TExecResult> => {

	type opt = {
		input: (TExecInput | undefined)
		callback: (TExecCallback | undefined)
		capture: boolean
		infile: (string | undefined)
		outfile: (string | undefined)
		}

	const {input, callback, capture, infile, outfile
			} = getOptions<opt>(hOptions, {
		input: undef,
		callback: undef,
		capture: false,
		infile: undef,
		outfile: undef
		})

	DBG(`execCmd: ${getCmdLine(cmdName, lArgs)}`)

	const pipeStdin  = anyDefined(input, infile)
	const pipeStdout = pipeStdin || capture || anyDefined(callback, outfile)

	if (!pipeStdout && !pipeStdin) {
		const child = Deno.spawn(cmdName, lArgs)
		const status = await child.status
		return {success: status.success}
	}

	const cmd: Deno.Command = new Deno.Command(cmdName, {
		args: lArgs,
		env: {DEFAULT_LOGGER: curLogLevel()},
		stdin:  pipeStdin  ? 'piped' : 'inherit',
		stdout: pipeStdout ? 'piped' : 'inherit',
		stderr: 'piped'
		})
	const child: Deno.ChildProcess = cmd.spawn()

	if (defined(infile)) {
		assert(notdefined(input), "Can't use both infile and input")
		const contents = await Deno.readTextFile(infile)
		const iter = allLinesIn(contents, true)
		ReadableStream.from(iter)
			.pipeThrough(new TextEncoderStream())
			.pipeTo(child.stdin)
	}
	else if (defined(input)) {
		// --- type of child.stdin is WritableStream<Uint8Array>
		const lStrings = (
			(await (async ()=>{if (isString(input)) {
				return Array.from(allLinesIn(input, true))
			}
			else if (isAsyncIterator(input)) {
				return await Array.fromAsync(input)
			}
			else if (isIterator(input)) {
				return Array.from(input)
			}
			else if (isArray(input)) {
				return input
			}
			else {
				return croak("Bad input")
			}})())
			)

		ReadableStream.from(lStrings)
			.pipeThrough(new TextEncoderStream())
			.pipeTo(child.stdin)
	}

	// --- Create a WritableStream that output can be sent to
	// --- type of child.stdout is WritableStream<Uint8Array>

	let stdout: string = ''
	const f = defined(outfile) ? new CWritableFile(outfile) : undef
	const outStrm: WritableStream<string> = (
		(defined(callback)?
			new WritableStream<string>({
				async write(chunk) {
					callback(chunk)
					if (defined(f)) {
						await f.write(chunk)
					}
					if (capture) {
						stdout += chunk
					}
					return
				}
				})
		:
			new WritableStream<string>({
				async write(chunk) {
					stdout += chunk
					if (defined(f)) {
						await f.write(chunk)
					}
					return
				}
				}))
		)

	await (
		child.stdout
		  .pipeThrough(new TextDecoderStream())
		  .pipeTo(outStrm, {preventClose: true})
			)
	const status = await child.status

	// --- putting this, even with the await keyword
	//     in the returned hash, fails
	const stderr = await child.stderr.text()

	return {
		success: status.success,
		stdout,
		stderr,
		...(infile && {infile}),
		...(outfile && {outfile})
		}
}

// ---------------------------------------------------------------------------

export abstract class CFileHandler {

	abstract get op(): string

	// ..........................................................
	// ASYNC

	async needed(
			path: string,
			hOptions: hash = {}
			): AutoPromise<boolean> {

		return true
	}

	// ..........................................................
	// ASYNC
	// --- if error occurs, throw an Error object

	abstract handle(
			path: string,
			hOptions: hash
			): Promise<TExecResult>

	// ..........................................................
	// ASYNC

	async handleFile(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		const force = ('force' in hOptions) && hOptions.force
		const isNeeded = await this.needed(path, hOptions)
		if (!force && !isNeeded) {
			return {
				success: true,
				notNeeded: true,
				infile: path
				}
		}
		const hResult = await this.handle(path, hOptions)
		return Object.assign(hResult, {infile: path})
	}

	// ..........................................................
	// SYNC

	getOutput(hResult: TExecResult): string {

		return (hResult?.stdout || '') + (hResult?.stderr || '')
	}
}

