class CFileRemover extends CFileHandler {

	get op() {
		return 'doRemoveFile'
	}

	override async needed(path: string): AutoPromise<boolean> {
		return await exists(path)
	}

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		LOG(`Removing file ${path}`)
		await Deno.remove(path)
		return {success: true}
	}
}

export const doRemoveFile = new CFileRemover()

// ---------------------------------------------------------------------------

class CTsFileRemover extends CFileHandler {

	get op() {
		return 'doRemoveTsFile'
	}

	override async needed(
			path: string
			): AutoPromise<boolean> {

		if (!await exists(path)) {
			return false
		}
		return await exists(withExt(path, '.civet'))
	}

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		assert((fileExt(path) === '.ts'), `Not a TypeScript file: ${path}`)
		await Deno.remove(path)
		return {
			success: true
			}
	}
}

export const doRemoveTsFile = new CTsFileRemover()

// ---------------------------------------------------------------------------
// ASYNC

export const isInstalled = async (scriptName: string): AutoPromise<boolean> => {

	const homeDir = Deno.env.get("HOME") ?? Deno.env.get("USERPROFILE") ?? ""
	const ext = (Deno.build.os === "windows") ? ".cmd" : ""
	const path = `${homeDir}/.deno/bin/${scriptName}${ext}`
	const isThere = await exists(path)
	if (isThere) {
		const fileInfo = await Deno.stat(path)
		return fileInfo.isFile
	}
	else {
		return false
	}
}

// ---------------------------------------------------------------------------

export const getCmdName = (
		path: string,
		hOptions: hash
		): string => {

	if (('name' in hOptions) && (typeof hOptions.name === 'string')) {
		return hOptions.name as string
	}
	else {
		return parsePath(path).stub.replaceAll('.', '_')
	}
}

