class CCivetCompiler extends CFileHandler {

	get op() {
		return 'doCompileCivet'
	}

	// ..........................................................

	override async needed(
			path: string,
			hOptions: hash = {}
			): AutoPromise<boolean> {

		return toBool(hOptions.force) || !newerDestFileExists(path, '.ts')
	}

	// ..........................................................

	getOutPath(
			path: string,
			output: string   // --- '.ts' or actual file name
			): string {

		assert((fileExt(path) === '.civet'), "Not a civet file")
		if (output === '.ts') {
			return withExt(path, '.ts')
		}
		else if (isFullPath(output)) {
			croak("output can't be a full path")
		}
		else {
			assert((fileExt(output) === '.ts'), "output must have .ts ext")
			return inSameDir(path, output)
		}
		return ''
	}

	// ..........................................................
	// ASYNC

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		const {force, nocheck, output, inlineMap,
			} = getOptions<TCivetOptions>(hOptions, {
				force: false,
				nocheck: false,
				output: '.ts',
				inlineMap: true
				})

		assert((fileExt(path) === '.civet'), `Not a civet file: ${path}`)
		const tsPath = withExt(path, '.ts')
		try {
			const outPath = await civet2tsFile(path, tsPath, {
				inlineMap,
				force,
				nocheck
				})
			assert((outPath === tsPath), `Bad output file: '${outPath}'`)
			return {
				success: true,
				infile: path,
				outfile: outPath
				}
		}
		catch (err) {
			const errMsg = getErrStr(err)
			if (debugging) {
				LOG(errMsg)
			}
			return {
				success: false,
				stderr: `COMPILE FAILED: ${pathStr(path)} - ${errMsg}`
				}
		}
	}
}

export const doCompileCivet = new CCivetCompiler()

